const scanMedianSample = `-- name: ScanMedianSample :many
SELECT view_count FROM rival_videos
WHERE channel_id = $1
ORDER BY position, id
LIMIT 150
`

// Mẫu trung vị: 150 hàng mới nhất theo thứ tự kênh, lấy view_count (null rơi ra
// khi tính median, không phải khi chọn mẫu).
func (q *Queries) ScanMedianSample(ctx context.Context, channelID string) ([]pgtype.Int8, error) {
	rows, err := q.db.Query(ctx, scanMedianSample, channelID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []pgtype.Int8{}
	for rows.Next() {
		var view_count pgtype.Int8
		if err := rows.Scan(&view_count); err != nil {
			return nil, err
		}
		items = append(items, view_count)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

