const scanRunnableJobs = `-- name: ScanRunnableJobs :many
SELECT id, channel_id, kind, state, requested_cap, cursor, cursor_at, remainder, replay_target, last_video_id, order_base, next_ordinal, anchors, newest_id, pages, scanned, added, attempts, restarts, next_attempt_at, error_code, last_error, recovery, reached_end, task_id, created_at, started_at, updated_at, finished_at FROM scan_jobs
WHERE (state IN ('queued', 'running')
       OR (state = 'backoff' AND next_attempt_at <= $1::timestamptz))
  AND channel_id <> ALL($2::text[])
ORDER BY CASE kind WHEN 'discovery' THEN 0 ELSE 1 END, updated_at, id
LIMIT 50
`

type ScanRunnableJobsParams struct {
	Now  pgtype.Timestamptz `json:"now"`
	Skip []string           `json:"skip"`
}

// Việc chạy được ngay: queued, running (worker chết để lại), backoff đã tới
// hạn — trừ các kênh mà nơi gọi đang bận. Tập bận lọc ngay trong câu truy vấn
// trước LIMIT: nếu lọc sau, 50 dòng bận đầu tiên sẽ che mất việc của kênh thứ
// 51 đang rảnh và worker quay lại đúng tiền tố đó. Discovery trước, rồi việc ít
// được đụng nhất.
func (q *Queries) ScanRunnableJobs(ctx context.Context, arg ScanRunnableJobsParams) ([]ScanJob, error) {
	rows, err := q.db.Query(ctx, scanRunnableJobs, arg.Now, arg.Skip)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ScanJob{}
	for rows.Next() {
		var i ScanJob
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.Kind,
			&i.State,
			&i.RequestedCap,
			&i.Cursor,
			&i.CursorAt,
			&i.Remainder,
			&i.ReplayTarget,
			&i.LastVideoID,
			&i.OrderBase,
			&i.NextOrdinal,
			&i.Anchors,
			&i.NewestID,
			&i.Pages,
			&i.Scanned,
			&i.Added,
			&i.Attempts,
			&i.Restarts,
			&i.NextAttemptAt,
			&i.ErrorCode,
			&i.LastError,
			&i.Recovery,
			&i.ReachedEnd,
			&i.TaskID,
			&i.CreatedAt,
			&i.StartedAt,
			&i.UpdatedAt,
			&i.FinishedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

